var Negotiator = require('./index');
function test() {
  var req = { headers: { accept: 'text/html, application/json' } };
  var n = new Negotiator(req);
  console.log('mediaTypes preferred', n.mediaTypes(['text/html','application/json'], { preferred: ['application/json'] }));
  console.log('mediaType preferred', n.mediaType(['text/html','application/json'], { preferred: ['application/json'] }));
  var req2 = { headers: { 'accept-language': 'en, fr;q=0.5' } };
  var n2 = new Negotiator(req2);
  console.log('languages preferred q test', n2.languages(['en','fr'], { preferred: ['fr'] }));
  console.log('languages tie break', n2.languages(['fr','en']));
  var req3 = { headers: { accept: 'text/html, application/json' } };
  var n3 = new Negotiator(req3);
  console.log('mediaTypes without preferred', n3.mediaTypes(['text/html','application/json']));
  console.log('mediaTypes reverse order tie', n3.mediaTypes(['application/json','text/html'], {preferred:['text/html']}));
  var req4 = { headers: { 'accept-charset': 'utf-8, iso-8859-1' } };
  var n4 = new Negotiator(req4);
  console.log('charsets preferred', n4.charsets(['utf-8','iso-8859-1'], {preferred:['iso-8859-1']}));
  console.log('charset preferred', n4.charset(['utf-8','iso-8859-1'], {preferred:['iso-8859-1']}));
  var req5 = { headers: { 'accept-language': 'en, fr' } };
  var n5 = new Negotiator(req5);
  console.log('languages preferred tie', n5.languages(['en','fr'], {preferred:['fr']}));
  console.log('language preferred tie', n5.language(['en','fr'], {preferred:['fr']}));
  // q still wins
  var req6 = { headers: { 'accept-language': 'en, fr;q=0.5' } };
  var n6 = new Negotiator(req6);
  console.log('languages q test 2', n6.languages(['en','fr'], {preferred:['fr']}));
  // mediaTypes q test
  var req7 = { headers: { accept: 'text/html;q=0.5, application/json' } };
  var n7 = new Negotiator(req7);
  console.log('mediaTypes q test', n7.mediaTypes(['text/html','application/json'], {preferred:['text/html']}));
}
test();
"

